#!/usr/bin/env node

/**
 * post_message.cjs - Post a message to Slack via chat.postMessage or an incoming webhook.
 *
 * Requires Node.js 18+ (global fetch) and either SLACK_BOT_TOKEN or SLACK_WEBHOOK_URL.
 *
 * Usage:
 *   SLACK_BOT_TOKEN=xoxb-... node post_message.cjs --channel "#general" --text "Hello"
 *   SLACK_BOT_TOKEN=xoxb-... node post_message.cjs --channel C123456 --text "Reply" --thread-ts 1234567890.123456
 *   SLACK_BOT_TOKEN=xoxb-... node post_message.cjs --channel "#announcements" --blocks '{"blocks":[{"type":"section","text":{"type":"mrkdwn","text":"*Bold* announcement"}}]}'
 *   SLACK_WEBHOOK_URL=https://hooks.slack.com/services/... node post_message.cjs --text "Hello via webhook"
 */

function parseArgs(argv) {
  const args = {};
  for (let i = 2; i < argv.length; i++) {
    const arg = argv[i];
    if (!arg.startsWith('--')) continue;
    const key = arg.slice(2);
    const next = argv[i + 1];
    if (next !== undefined && !next.startsWith('--')) {
      args[key] = next;
      i++;
    } else {
      args[key] = true;
    }
  }
  return args;
}

async function main() {
  const args = parseArgs(process.argv);
  const token = process.env.SLACK_BOT_TOKEN;
  const webhookUrl = process.env.SLACK_WEBHOOK_URL;

  if (!token && !webhookUrl) {
    process.stderr.write('Failure: Set SLACK_BOT_TOKEN or SLACK_WEBHOOK_URL.\n');
    process.exit(1);
  }
  if (!args.text && !args.blocks) {
    process.stderr.write('Failure: Provide --text and/or --blocks.\n');
    process.exit(1);
  }
  if (args.blocks) {
    try {
      JSON.parse(args.blocks);
    } catch (err) {
      process.stderr.write(`Failure: --blocks is not valid JSON: ${err.message}\n`);
      process.exit(1);
    }
  }

  // Incoming webhook path: text and/or blocks only.
  if (webhookUrl && !token) {
    const payload = {};
    if (args.text) payload.text = args.text;
    if (args.blocks) payload.blocks = JSON.parse(args.blocks);
    const res = await fetch(webhookUrl, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    });
    if (!res.ok) {
      const detail = await res.text();
      process.stderr.write(`Failure: webhook returned HTTP ${res.status}: ${detail || 'no detail'}\n`);
      process.exit(1);
    }
    process.stdout.write('Success: Message posted via webhook.\n');
    return;
  }

  // Web API path.
  const payload = { channel: args.channel, text: args.text || '' };
  if (args.blocks) payload.blocks = JSON.parse(args.blocks);
  if (args['thread-ts']) payload.thread_ts = args['thread-ts'];

  const res = await fetch('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${token}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(payload),
  });

  if (res.status === 429) {
    const retryAfter = Number(res.headers.get('Retry-After') || 1);
    process.stderr.write(`Failure: rate limited; retry after ${retryAfter}s.\n`);
    process.exit(1);
  }

  const body = await res.json();
  if (!body.ok) {
    const detail = (body.response_metadata && body.response_metadata.messages)
      ? body.response_metadata.messages.join('; ')
      : '';
    process.stderr.write(`Failure: ${body.error}${detail ? ` (${detail})` : ''}\n`);
    process.exit(1);
  }

  process.stdout.write(`Success: Message ${body.ts} posted to ${body.channel}.\n`);
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});

#!/usr/bin/env node

/**
 * list_channels.cjs - List Slack channels via conversations.list with cursor pagination.
 *
 * Requires Node.js 18+ (global fetch) and SLACK_BOT_TOKEN.
 *
 * Usage:
 *   SLACK_BOT_TOKEN=xoxb-... node list_channels.cjs
 *   SLACK_BOT_TOKEN=xoxb-... node list_channels.cjs --types public_channel,private_channel --exclude-archived
 *   SLACK_BOT_TOKEN=xoxb-... node list_channels.cjs --types im --limit 500
 */

function argValue(argv, key) {
  const i = argv.indexOf(key);
  return i >= 0 && argv[i + 1] !== undefined ? argv[i + 1] : undefined;
}

async function main() {
  const token = process.env.SLACK_BOT_TOKEN;
  if (!token) {
    process.stderr.write('Failure: Set SLACK_BOT_TOKEN.\n');
    process.exit(1);
  }

  const argv = process.argv.slice(2);
  const types = argValue(argv, '--types') || 'public_channel';
  const limit = Number(argValue(argv, '--limit') || '200');
  const excludeArchived = argv.includes('--exclude-archived');

  const channels = [];
  let cursor = '';

  do {
    const params = new URLSearchParams({
      types,
      limit: String(Math.min(limit, 200)),
      exclude_archived: excludeArchived ? 'true' : 'false',
    });
    if (cursor) params.set('cursor', cursor);

    const res = await fetch(`https://slack.com/api/conversations.list?${params}`, {
      headers: { Authorization: `Bearer ${token}` },
    });

    if (res.status === 429) {
      const retryAfter = Number(res.headers.get('Retry-After') || 1);
      process.stderr.write(`Failure: rate limited; retry after ${retryAfter}s.\n`);
      process.exit(1);
    }

    const body = await res.json();
    if (!body.ok) {
      process.stderr.write(`Failure: ${body.error}\n`);
      process.exit(1);
    }

    channels.push(...(body.channels || []));
    cursor = (body.response_metadata && body.response_metadata.next_cursor) || '';
  } while (cursor && channels.length < limit);

  if (channels.length === 0) {
    process.stdout.write('Success: No channels found.\n');
    return;
  }

  const lines = channels.map((c) => {
    const flags = [
      c.is_private ? 'private' : 'public',
      c.is_member ? 'member' : 'not-member',
      c.is_archived ? 'archived' : '',
    ]
      .filter(Boolean)
      .join(',');
    return `#${c.name} (${c.id}) [${flags}]`;
  });

  process.stdout.write(`Success: Found ${channels.length} channel(s):\n${lines.join('\n')}\n`);
}

main().catch((err) => {
  process.stderr.write(`Failure: ${err.message}\n`);
  process.exit(1);
});
